def transform(g):
    h, w = len(g), len(g[0])
    out = [row[:] for row in g]
    objects = []
    for color in range(1, 10):
        for r in range(h - 2):
            for c in range(w - 2):
                if all(g[y][x] == color for y in range(r, r + 3) for x in range(c, c + 3)):
                    objects.append((color, r + 1, c + 1))
    for color, r, c in objects:
        for x in range(w): out[r][x] = color
        for y in range(h): out[y][c] = color
    for i, (a, r, c) in enumerate(objects):
        for b, s, d in objects[i + 1:]:
            if a != b:
                out[r][d] = 0
                out[s][c] = 0
    return out
